/**
 * Simplified NBA Predictions Function
 * 
 * This function reads precomputed predictions from static JSON
 * (generated by GitHub Actions) and returns them.
 * 
 * No heavy computation - just read and serve.
 * Target execution time: <2 seconds
 * 
 * URL: /.netlify/functions/nba-predictions-simple
 */

export default async (req, context) => {
  // Handle CORS preflight
  if (req.method === 'OPTIONS') {
    return new Response(null, {
      status: 204,
      headers: {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'GET, OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type'
      }
    });
  }

  const startTime = Date.now();

  try {
    console.log('🏀 NBA Predictions (Simple Mode) - Reading precomputed data...');

    // Read the precomputed predictions JSON from static site
    // GitHub Actions writes to public/data/nba/predictions-latest.json
    // Netlify serves public/ at the site root
    const baseUrl = process.env.URL || 'https://bgroundrobin.com';
    const predictionsUrl = `${baseUrl}/data/nba/predictions-latest.json`;
    
    console.log(`📥 Fetching from: ${predictionsUrl}`);
    
    const response = await fetch(predictionsUrl);
    
    if (!response.ok) {
      throw new Error(`Failed to fetch predictions: HTTP ${response.status}`);
    }
    
    const predictions = await response.json();
    
    const elapsed = Date.now() - startTime;
    console.log(`✅ Loaded predictions in ${elapsed}ms`);
    console.log(`📊 Total picks: ${predictions.recommendations?.length || 0}`);
    
    // Add metadata
    predictions.loadedAt = new Date().toISOString();
    predictions.loadTime = `${elapsed}ms`;
    
    return new Response(JSON.stringify(predictions), {
      status: 200,
      headers: {
        'Content-Type': 'application/json',
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'GET, OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type',
        'Cache-Control': 'public, max-age=300' // Cache for 5 minutes
      }
    });

  } catch (error) {
    console.error('❌ Error:', error);
    
    const elapsed = Date.now() - startTime;
    
    return new Response(JSON.stringify({ 
      error: error.message,
      timestamp: new Date().toISOString(),
      elapsed: `${elapsed}ms`,
      details: 'Predictions may not be available yet. GitHub Actions generates predictions at 6:30 AM, 12:05 PM, and 6:45 PM ET.'
    }), {
      status: 500,
      headers: { 
        'Content-Type': 'application/json',
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'GET, OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type'
      }
    });
  }
};
